const existingUrlsSet = new Set($input.first().json.existing_urls || []);
const newJobs = $('Merge 6 Final').all();

const REJECT_PATTERNS = [
  /\bus[\s\-]only\b/i, /\bunited[\s\-]states[\s\-]only\b/i,
  /\bcanada[\s\-]only\b/i, /\buk[\s\-]only\b/i,
  /\beu[\s\-]only\b/i, /\beurope[\s\-]only\b/i,
  /\baustralia[\s\-]only\b/i,
  /\bmust\s+be\s+based\s+in\b/i,
  /\bmust\s+live\s+in\b/i,
  /\bauthorized\s+to\s+work\s+in\b/i,
  /\blocal\s+work\s+permit\b/i,
  /\bhybrid\s+role\b/i, /\boffice\s+required\b/i,
  /\bonsite\b/i, /\bon[\s\-]site\b/i,
  /\bin[\s\-]person\s+required\b/i,
  /\bremote\s+within\s+(the\s+)?(us|uk|eu|canada|australia)\b/i,
  /\bfixed\s+(us|eu|est|pst|cet)\s+hours\b/i,
  /\bno\s+international\s+applicants\b/i
];

const ROLE_KEYWORDS = [
  'data analyst', 'data scientist', 'business intelligence', ' bi ', 'bi analyst',
  'marketing analyst', 'growth analyst', 'performance marketing',
  'ai marketing', 'ai automation', 'ai workflow', 'automation specialist',
  'automation engineer', 'martech', 'marketing data', 'analytics engineer',
  'analytics', 'tableau', 'power bi', 'looker', 'dbt',
  'marketing operations', 'revenue operations', 'growth hacking',
  'sql analyst', 'data engineer', 'reporting analyst',
  'insights analyst', 'digital marketing', 'seo specialist', 'seo analyst',
  'ppc specialist', 'paid media', 'paid search', 'paid social',
  'creative strategist', 'content analyst', 'attribution analyst',
  'ga4', 'google analytics', 'meta ads', 'google ads', 'programmatic',
  'machine learning', 'ml engineer', 'growth analyst'
];

const seenUrls = new Set(existingUrlsSet);
const results = [];

for (const item of newJobs) {
  const job = item.json;
  const url = (job.job_url || '').trim();
  if (!url) continue;

  // Dedup
  if (seenUrls.has(url)) continue;
  const companyKey = (job.company + '___' + job.job_title).toLowerCase();
  if (seenUrls.has(companyKey)) continue;
  seenUrls.add(url);
  seenUrls.add(companyKey);

  const searchText = (job.job_title + ' ' + job.description + ' ' + (job.tags || '')).toLowerCase();

  // Role pre-filter
  const hasRole = ROLE_KEYWORDS.some(kw => searchText.includes(kw));
  if (!hasRole) continue;

  // Taiwan hard filter
  const fullText = job.job_title + ' ' + job.location_text + ' ' + job.description;
  const isRejected = REJECT_PATTERNS.some(p => p.test(fullText));
  if (isRejected) continue;

  results.push({ json: job });
}

return results;

const items = $input.all();
return items.map(item => {
  const job = item.json;
  let aiResult = {};
  try {
    const rawContent = job.message?.content || job.content || '{}';
    const jsonMatch = rawContent.match(/\{[\s\S]*\}/);
    if (jsonMatch) aiResult = JSON.parse(jsonMatch[0]);
  } catch(e) {
    aiResult = { taiwan_eligible: 'unclear', reason: 'Parse error', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
  }

  if (aiResult.decision === 'reject' || aiResult.taiwan_eligible === 'no') {
    return { json: { ...job, ...aiResult, score: 0, _rejected: true, _reject_reason: 'AI: ' + (aiResult.reason || 'not Taiwan eligible') } };
  }

  const desc = (job.description + ' ' + job.job_title + ' ' + (job.tags || '') + ' ' + (job.location_text || '')).toLowerCase();

  // Async filter
  const ASYNC_REJECT = ['strict 9 to 5', 'fixed us hours', 'fixed est hours', 'fixed pst hours', 'fixed cet hours', 'must overlap full business day', 'daily live calls required'];
  if (ASYNC_REJECT.some(kw => desc.includes(kw))) {
    return { json: { ...job, ...aiResult, score: 0, async_level: 'blocking', _rejected: true, _reject_reason: 'Async filter: fixed hours conflict' } };
  }

  let async_level, async_score;
  if (['async', 'asynchronous', 'async-first', 'no meetings', 'async first'].some(kw => desc.includes(kw))) { async_level = 'high'; async_score = 25; }
  else if (['flexible hours', 'flexible schedule', 'work across time zones', 'distributed team'].some(kw => desc.includes(kw))) { async_level = 'medium'; async_score = 20; }
  else if (['remote first', 'remote-first', 'low meeting'].some(kw => desc.includes(kw))) { async_level = 'low-medium'; async_score = 15; }
  else { async_level = 'unknown'; async_score = 10; }

  // Taiwan score
  const twStatus = aiResult.taiwan_eligible || 'unclear';
  const locRisk = aiResult.location_risk || 'medium';
  let taiwan_score = 0;
  if (twStatus === 'yes' && locRisk === 'low') taiwan_score = 40;
  else if (twStatus === 'yes') taiwan_score = 35;
  else if (desc.includes('apac') || desc.includes('asia')) taiwan_score = 30;
  else if (twStatus === 'unclear' && locRisk !== 'high') taiwan_score = 20;
  else taiwan_score = 0;

  // Role score
  const titleText = (job.job_title + ' ' + (job.tags || '')).toLowerCase();
  const ROLE_CORE = ['data analyst', 'data scientist', 'bi analyst', 'business intelligence analyst', 'marketing analyst', 'growth analyst', 'ai marketing', 'ai automation', 'automation specialist', 'performance marketing analyst', 'martech analyst', 'marketing data'];
  const ROLE_ADJ = ['analytics', 'digital marketing', 'seo', 'paid media', 'data engineer', 'reporting analyst', 'insights analyst', 'marketing operations', 'paid search', 'paid social', 'ga4', 'google analytics'];
  let role_category, role_score;
  if (ROLE_CORE.some(kw => titleText.includes(kw))) { role_category = 'core'; role_score = 25; }
  else if (ROLE_ADJ.some(kw => titleText.includes(kw))) { role_category = 'adjacent'; role_score = 15; }
  else { role_category = 'other'; role_score = 5; }

  // Salary score
  const salaryText = (job.salary || '').replace(/,/g, '');
  let salary_score = 0;
  const nums = salaryText.match(/\d+/g);
  if (nums) {
    const n = parseInt(nums[0]);
    const isAnnual = salaryText.includes('year') || salaryText.includes('annual') || n > 50000;
    const monthly = isAnnual ? Math.round(n / 12) : n;
    if (monthly >= 5000) salary_score = 25;
    else if (monthly >= 3000) salary_score = 15;
    else salary_score = 10;
  } else if (salaryText.length > 2) {
    salary_score = 10;
  }

  const score = taiwan_score + async_score + role_score + salary_score;

  const why_parts = [];
  if (taiwan_score >= 35) why_parts.push('Taiwan-friendly');
  if (async_score >= 20) why_parts.push('async culture');
  if (role_score >= 25) why_parts.push('strong role fit');
  if (salary_score >= 15) why_parts.push('good salary');
  const why_good_fit = why_parts.join(', ') || 'Needs manual review';

  return {
    json: {
      ...job,
      taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
      taiwan_reason: aiResult.reason || '',
      location_risk: aiResult.location_risk || 'medium',
      timezone_risk: aiResult.timezone_risk || 'medium',
      contractor_possible: aiResult.contractor_possible || 'unclear',
      decision: aiResult.decision || 'manual_check',
      async_level,
      role_category,
      why_good_fit,
      score,
      _rejected: false
    }
  };
});

