const item = $input.first();
const allJobs = item.json.all_jobs || [];
const rejected = allJobs.filter(j => j.score < 70 || j.taiwan_eligible === 'no' || j._rejected);
return rejected.map(j => ({
  json: {
    date_rejected: new Date().toISOString(),
    job_title: j.job_title,
    company: j.company,
    job_url: j.job_url,
    reason: j._reject_reason || (j.score < 70 ? ('Low score: ' + j.score) : 'Not Taiwan eligible')
  }
}));

const item = $input.first();
const allJobs = item.json.all_jobs || [];

const filtered = allJobs.filter(j => j.score >= 70 && j.taiwan_eligible !== 'no' && !j._rejected);
const rejected = allJobs.filter(j => j.score < 70 || j.taiwan_eligible === 'no' || j._rejected);
filtered.sort((a, b) => (b.score || 0) - (a.score || 0));

const topJobs = filtered.slice(0, 10);
const manualCheck = filtered.filter(j => j.decision === 'manual_check' || j.taiwan_eligible === 'unclear').slice(0, 5);

const countReject = (keyword) => rejected.filter(j => (j._reject_reason || '').toLowerCase().includes(keyword)).length;
const rejectedUS = countReject('us only') + countReject('united states');
const rejectedEU = countReject('eu') + countReject('europe');
const rejectedHybrid = countReject('hybrid') + countReject('onsite');
const rejectedTZ = rejected.filter(j => j.timezone_risk === 'high' || (j._reject_reason || '').includes('hours')).length;
const rejectedLowScore = rejected.filter(j => j.score < 70 && !j._reject_reason?.includes('only') && !j._reject_reason?.includes('hybrid')).length;

const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Taipei' });

let html = `<div style="font-family:sans-serif;max-width:700px;margin:auto">`;
html += `<h2 style="color:#4f46e5">🌏 Daily Taiwan Eligible Async Remote Jobs</h2>`;
html += `<p style="color:#666">${today}</p>`;
html += `<p><strong>Total checked:</strong> ${allJobs.length} &nbsp;|&nbsp; <strong>Passed:</strong> ${filtered.length} &nbsp;|&nbsp; <strong>Rejected:</strong> ${rejected.length}</p>`;

if (topJobs.length === 0) {
  html += `<p>No qualifying jobs found today. Try again tomorrow.</p>`;
} else {
  html += `<h3>🏆 Top Jobs Today (${topJobs.length})</h3>`;
  topJobs.forEach((job, i) => {
    const scoreColor = job.score >= 85 ? '#16a34a' : job.score >= 70 ? '#4f46e5' : '#64748b';
    html += `<div style="border-left:4px solid ${scoreColor};margin-bottom:20px;padding:12px;background:#f9f9f9;border-radius:0 8px 8px 0">`;
    html += `<h4 style="margin:0 0 8px">${i+1}. ${job.job_title}</h4>`;
    html += `<p style="margin:4px 0"><strong>Company:</strong> ${job.company}</p>`;
    html += `<p style="margin:4px 0"><strong>Score:</strong> <span style="color:${scoreColor};font-weight:bold">${job.score}/100</span></p>`;
    html += `<p style="margin:4px 0"><strong>Taiwan Eligible:</strong> ${job.taiwan_eligible} — ${job.taiwan_reason}</p>`;
    html += `<p style="margin:4px 0"><strong>Async Level:</strong> ${job.async_level} &nbsp;|&nbsp; <strong>Timezone Risk:</strong> ${job.timezone_risk}</p>`;
    html += `<p style="margin:4px 0"><strong>Salary:</strong> ${job.salary || 'Not listed'}</p>`;
    html += `<p style="margin:4px 0"><strong>Why it fits Jerry:</strong> ${job.why_good_fit}</p>`;
    html += `<a href="${job.job_url}" style="display:inline-block;margin-top:8px;background:#4f46e5;color:#fff;padding:6px 14px;text-decoration:none;border-radius:4px">Apply →</a>`;
    html += `</div>`;
  });
}

if (manualCheck.length > 0) {
  html += `<h3>🔍 Manual Check Needed (${manualCheck.length})</h3><ul>`;
  manualCheck.forEach(job => {
    html += `<li><a href="${job.job_url}">${job.job_title}</a> at ${job.company} — Score: ${job.score} — ${job.taiwan_reason}</li>`;
  });
  html += `</ul>`;
}

html += `<h3>❌ Rejected Summary</h3>`;
html += `<ul style="color:#666">`;
html += `<li>US only / work authorization: ${rejectedUS}</li>`;
html += `<li>EU only: ${rejectedEU}</li>`;
html += `<li>Hybrid / Onsite: ${rejectedHybrid}</li>`;
html += `<li>Timezone conflict: ${rejectedTZ}</li>`;
html += `<li>Low score (below 70): ${rejectedLowScore}</li>`;
html += `</ul>`;
html += `</div>`;

return [{ json: { digest_html: html, job_count: filtered.length, today } }];
